<?php foreach ($rows as $row): $status = (string) ($row['billing_status'] ?? 'not_exported'); $statusLabel = ['not_exported'=>'Nicht exportiert','export_pending'=>'Export läuft','exported'=>'Exportiert','export_failed'=>'Fehlgeschlagen','manually_unexported'=>'Manuell zurückgesetzt'][$status] ?? $status; $statusClass = $status === 'exported' ? 'success' : (in_array($status, ['export_failed'], true) ? 'danger' : (in_array($status, ['manually_unexported'], true) ? 'warning text-dark' : 'secondary')); ?><tr><td><?php if (($row['billing_eligibility'] ?? '') === 'billable' && $status !== 'exported'): ?><input class="billing-check" type="checkbox" name="inspection_ids[]" value="<?= (int) $row['id'] ?>"><?php endif; ?></td><td><a href="<?= htmlspecialchars(url_for('admin/pruefungen/' . (int) $row['id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) $row['external_number']) ?></a></td><td><?= htmlspecialchars((string) $row['test_date']) ?></td><td><?= htmlspecialchars((string) $row['customer_name']) ?></td><td><a href="<?= htmlspecialchars(url_for('geraete?device_id=' . (int) $row['device_id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) $row['device_number']) ?> · <?= htmlspecialchars((string) $row['device_name']) ?></a></td><td><span class="badge text-bg-<?= $statusClass ?>"><?= htmlspecialchars($statusLabel) ?></span><?php if (($row['billing_eligibility'] ?? '') === 'not_billable'): ?><div class="small text-body-secondary"><?= htmlspecialchars((string) ($row['billing_not_billable_reason'] ?? 'Nicht abrechenbar')) ?></div><?php endif; ?><?php if (($row['billing_last_error'] ?? '') !== ''): ?><div class="small text-danger"><?= htmlspecialchars((string) $row['billing_last_error']) ?></div><?php endif; ?></td><td><?php if (!empty($row['invoice_id'])): ?><a href="<?= htmlspecialchars(url_for('admin/abrechnung/rechnung/' . (int) $row['invoice_id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) ($row['invoice_number'] ?: '#' . $row['invoice_id'])) ?></a><?php else: ?>—<?php endif; ?></td><td><div class="dropdown"><button class="btn btn-sm btn-outline-secondary dropdown-toggle" data-bs-toggle="dropdown" type="button"><i class="fa-solid fa-gear" aria-hidden="true"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><form method="post" action="<?= htmlspecialchars(url_for('admin/abrechnung/pruefung/' . (int) $row['id'] . '/abrechenbarkeit'), ENT_QUOTES) ?>" class="px-3 py-2"><input type="hidden" name="eligibility" value="<?= ($row['billing_eligibility'] ?? '') === 'billable' ? 'not_billable' : 'billable' ?>"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Grund (bei nicht abrechenbar)"><button class="btn btn-sm btn-primary" type="submit">Abrechenbarkeit ändern</button></form></li><?php if (current_user_is_superadmin() && $status === 'exported'): ?><li><hr class="dropdown-divider"></li><li><form method="post" action="<?= htmlspecialchars(url_for('admin/abrechnung/pruefung/' . (int) $row['id'] . '/export-zuruecksetzen'), ENT_QUOTES) ?>" class="px-3 py-2"><input type="hidden" name="confirm" value="1"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Reset-Grund" required><button class="btn btn-sm btn-danger" type="submit" onclick="return confirm('Diese Prüfung ist bereits abgerechnet. Wirklich zurücksetzen?');"><i class="fa-solid fa-triangle-exclamation me-1" aria-hidden="true"></i>Export zurücksetzen</button></form></li><?php endif; ?></ul></div></td></tr><?php endforeach; ?>
<?php if ($rows === []): ?><tr><td colspan="8" class="text-body-secondary">Keine Prüfungen für diesen Filter.</td></tr><?php endif; ?></tbody></table></div><div class="mt-3 d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-outline-success" name="action" value="set_billable"><i class="fa-solid fa-check me-1" aria-hidden="true"></i>Auswahl als abrechenbar markieren</button><button class="btn btn-sm btn-outline-secondary" name="action" value="set_not_billable"><i class="fa-solid fa-ban me-1" aria-hidden="true"></i>Auswahl als nicht abrechenbar markieren</button></div></div></div></form>
